class GravitationalForce {
public:
    GravitationalForce(const Point3D &p1, const Point3D &p2, double m1, double m2, double G) {
        this->p1 = p1;
        this->p2 = p2;
        this->m1 = m1;
        this->m2 = m2;
        this->G = G;
    }

    double calculateForce() {
        double r = point_distance(p1, p2);
        return this->G * this->m1 * this->m2 / (r * r);
    }

private:
