### 2. Code Generator: Point3D - 3D Vector Helper Class

```cpp
class Point3D {
public:
    Point3D(double x = 0, double y = 0, double z = 0) : x_(x), y_(y), z_(z) {}
    double x() const { return x_; } void setX(double x) { x_ = x; }
    double y() const { return y_; } void setY(double y) { y_ = y; }
    double z() const { return z_; } void setZ(double z) { z_ = z; }

    // Euclidean distance between two points
    static double point_distance(const Point3D &a, const Point3D &b) {
        double dx = a.x() - b.x();
        double dy = a.y() - b.y();
        double dz = a.z() - b.z();
        return sqrt(dx*dx + dy*dy + dz*dz);
    }

private:
    double x_, y_, z_;
};
```
**Explanation**: Utility for basic 3D vector arithmetic, including distance calculation between two points.

