Point3D VectorToDistance(const Point3D &src, const Point3D &dst, double distance) {
    Point3D dir = VectorSub(dst, src);
    double length = abs(dir.length());
    Point3D unit_dir = Point3D(dir.x() / length, dir.y() / length, dir.z() / length);
    return Point3D(unit_dir.x(), unit_dir.y(), unit_dir.z()) * distance;
}

Point3D VectorSub(const Point3D &src, const Point3D &dst) {
    return Point3D(src.x() - dst.x(), src.y() - dst.y(), src.z() - dst.z());
}
```
